for x in select value from jsonb_array_elements('[{"identity":"repo:https://github.com/openshot/openshot-qt","slug":"openshot-beb1924c","name":"OpenShot","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Một nơi ghép clip, tiêu đề và âm thanh cho video đầu tiên của bạn.","description":"OpenShot là trình dựng video desktop mở cho Linux, macOS và Windows. Dự án cung cấp các công cụ cắt ghép, nhiều lớp và animation để biến tư liệu rời thành một video có bố cục. Phù hợp thử workflow dựng thủ công hoặc kết hợp đầu ra từ AI.","long_description":"ĐIỂM NỔI BẬT\n• Timeline nhiều track/layer, cắt và biến đổi clip.\n• Animation theo keyframe, transition và điều chỉnh tốc độ.\n• Tiêu đề SVG, template chữ, xử lý âm thanh và hỗ trợ nhiều định dạng qua FFmpeg.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nDựng một clip giới thiệu tool gồm màn hình thao tác, tiêu đề từng bước, voice và nhạc nền.\n\nBẮT ĐẦU\nDùng bộ cài ổn định từ website; không coi bản daily build là bản đã kiểm thử production.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nTăng tốc phần cứng được README đánh dấu thử nghiệm. Nên lưu nhiều phiên bản project và kiểm tra xuất video trên máy của bạn.","canonical_url":"https://github.com/OpenShot/openshot-qt","repository_url":"https://github.com/OpenShot/openshot-qt","documentation_url":"https://raw.githubusercontent.com/OpenShot/openshot-qt/develop/README.md","owner_name":"OpenShot","license":"GPL-3.0-or-later theo README; thư viện và tài nguyên có thể có giấy phép riêng.","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":41,"categories":["video"],"primaryCategory":"video","selectionReason":"Phù hợp Video & Phụ đề: Một nơi ghép clip, tiêu đề và âm thanh cho video đầu tiên của bạn. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Một nơi ghép clip, tiêu đề và âm thanh cho video đầu tiên của bạn.","highlights":["Timeline nhiều track/layer, cắt và biến đổi clip.","Animation theo keyframe, transition và điều chỉnh tốc độ.","Tiêu đề SVG, template chữ, xử lý âm thanh và hỗ trợ nhiều định dạng qua FFmpeg."],"example":"Dựng một clip giới thiệu tool gồm màn hình thao tác, tiêu đề từng bước, voice và nhạc nền.","setup":"Dùng bộ cài ổn định từ website; không coi bản daily build là bản đã kiểm thử production.","limitations":"Tăng tốc phần cứng được README đánh dấu thử nghiệm. Nên lưu nhiều phiên bản project và kiểm tra xuất video trên máy của bạn.","github":{"stars":6423,"forks":786,"observedAt":"2026-09-03T16:08:15.622Z","url":"https://github.com/OpenShot/openshot-qt","pushedAt":"2026-09-01T03:31:09Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/OpenShot/openshot-qt/develop/README.md","observedAt":"2026-09-03T16:09:58.477Z","sha256":"ebc33ce9c6aea7d4b63cbd8f0e83dd5c52751252047c07fd0310ab56f4ef1513"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"OpenShot/openshot-qt:metadata","source_url":"https://github.com/OpenShot/openshot-qt","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3AFujiwaraChoki%2FMoneyPrinterV2%20repo%3ARayVentura%2FShortGPT%20repo%3AOpenCut-app%2FOpenCut%20repo%3Amifi%2Flossless-cut%20repo%3AHandBrake%2FHandBrake%20repo%3Aobsproject%2Fobs-studio%20repo%3Amltframework%2Fshotcut%20repo%3AOpenShot%2Fopenshot-qt&per_page=100","stars":6423,"forks":786,"license":"NOASSERTION"},"fetched_at":"2026-09-03T16:08:15.622Z"},{"source_type":"github","source_identifier":"OpenShot/openshot-qt:readme:ebc33ce9c6aea7d4b63cbd8f0e83dd5c52751252047c07fd0310ab56f4ef1513","source_url":"https://raw.githubusercontent.com/OpenShot/openshot-qt/develop/README.md","raw_metadata":{"sha256":"ebc33ce9c6aea7d4b63cbd8f0e83dd5c52751252047c07fd0310ab56f4ef1513","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:58.477Z"}],"expected":null},{"identity":"repo:https://github.com/kde/kdenlive","slug":"kdenlive-9ef8a2c6","name":"Kdenlive","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Dựng video nhiều lớp, sửa phụ đề và tinh chỉnh màu trong một project.","description":"Kdenlive là trình dựng video của KDE. GitHub là bản mirror chính thức; dự án phát triển trên hạ tầng KDE. Nó phù hợp khâu hoàn thiện thành phẩm sau khi đã có hình, voice và tư liệu.","long_description":"ĐIỂM NỔI BẬT\n• Timeline nhiều track và hỗ trợ nhiều định dạng qua FFmpeg.\n• Tiêu đề, hiệu ứng theo keyframe, chỉnh màu và âm thanh.\n• Proxy giúp dựng nhẹ hơn; có tính năng tạo phụ đề dùng mô hình giọng nói.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nGhép voice với cảnh minh họa, chỉnh phụ đề và xem lại toàn bộ nhịp trước khi xuất Shorts.\n\nBẮT ĐẦU\nTải bản ổn định từ Kdenlive; tách bản thử nghiệm khỏi dự án cần giao.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nProxy không thay thế bản gốc khi xuất. Mô hình phụ đề vẫn cần soát lỗi tên riêng và tiếng Việt.","canonical_url":"https://github.com/KDE/kdenlive","repository_url":"https://github.com/KDE/kdenlive","documentation_url":"https://raw.githubusercontent.com/KDE/kdenlive/master/README.md","owner_name":"KDE","license":"GPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":42,"categories":["video"],"primaryCategory":"video","selectionReason":"Phù hợp Video & Phụ đề: Dựng video nhiều lớp, sửa phụ đề và tinh chỉnh màu trong một project. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Dựng video nhiều lớp, sửa phụ đề và tinh chỉnh màu trong một project.","highlights":["Timeline nhiều track và hỗ trợ nhiều định dạng qua FFmpeg.","Tiêu đề, hiệu ứng theo keyframe, chỉnh màu và âm thanh.","Proxy giúp dựng nhẹ hơn; có tính năng tạo phụ đề dùng mô hình giọng nói."],"example":"Ghép voice với cảnh minh họa, chỉnh phụ đề và xem lại toàn bộ nhịp trước khi xuất Shorts.","setup":"Tải bản ổn định từ Kdenlive; tách bản thử nghiệm khỏi dự án cần giao.","limitations":"Proxy không thay thế bản gốc khi xuất. Mô hình phụ đề vẫn cần soát lỗi tên riêng và tiếng Việt.","github":{"stars":5593,"forks":495,"observedAt":"2026-09-03T16:08:22.123Z","url":"https://github.com/KDE/kdenlive","pushedAt":"2026-09-03T15:55:40Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/KDE/kdenlive/master/README.md","observedAt":"2026-09-03T16:10:03.733Z","sha256":"86f55bc195dc5ff81d82f52d1c4b10a17c411e6fc43a629be0c2a74708084f36"},"trending":null,"extraSources":["https://kdenlive.org/features/"]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"KDE/kdenlive:metadata","source_url":"https://github.com/KDE/kdenlive","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3AKDE%2Fkdenlive%20repo%3ASubtitleEdit%2Fsubtitleedit%20repo%3Ajianchang512%2Fpyvideotrans%20repo%3Akrillinai%2FKrillinAI%20repo%3AHuanshere%2FVideoLingo%20repo%3AChenyme%2FChenyme-AAVT%20repo%3Ayt-dlp%2Fyt-dlp%20repo%3AZulko%2Fmoviepy&per_page=100","stars":5593,"forks":495,"license":"GPL-3.0"},"fetched_at":"2026-09-03T16:08:22.123Z"},{"source_type":"github","source_identifier":"KDE/kdenlive:readme:86f55bc195dc5ff81d82f52d1c4b10a17c411e6fc43a629be0c2a74708084f36","source_url":"https://raw.githubusercontent.com/KDE/kdenlive/master/README.md","raw_metadata":{"sha256":"86f55bc195dc5ff81d82f52d1c4b10a17c411e6fc43a629be0c2a74708084f36","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:03.733Z"},{"source_type":"manual","source_identifier":"https://kdenlive.org/features/","source_url":"https://kdenlive.org/features/","raw_metadata":{"relationship":"MAINTAINER","usage":"official_documentation"},"fetched_at":"2026-09-03T16:12:52.012Z"}],"expected":null},{"identity":"repo:https://github.com/rvc-boss/gpt-sovits","slug":"gpt-sovits-205700d0","name":"GPT-SoVITS","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Từ mẫu giọng ngắn đến thử nghiệm TTS và bộ dữ liệu giọng riêng.","description":"GPT-SoVITS kết hợp TTS zero-shot/few-shot với WebUI hỗ trợ chuẩn bị dữ liệu. Tác giả minh họa mẫu vài giây và tinh chỉnh từ dữ liệu ngắn; đây là điều kiện demo, không bảo đảm mọi bản thu sẽ cho kết quả tương tự.","long_description":"ĐIỂM NỔI BẬT\n• Tổng hợp theo mẫu và tinh chỉnh giọng.\n• Có tách giọng, chia dữ liệu, ASR và gán văn bản trong WebUI.\n• README liệt kê Anh, Nhật, Hàn, Quảng Đông và Trung cho suy luận liên ngôn ngữ.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nChuẩn bị tập đọc của chính bạn để thử quy trình tạo voice ở ngôn ngữ được hỗ trợ.\n\nBẮT ĐẦU\nChọn gói Windows hoặc môi trường phù hợp theo hướng dẫn; tải model từ liên kết chính chủ.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nKhông mặc định hỗ trợ tiếng Việt. README cảnh báo huấn luyện GPU Mac có vấn đề chất lượng; kiểm tra quyền của dữ liệu, checkpoint và người có giọng được dùng.","canonical_url":"https://github.com/RVC-Boss/GPT-SoVITS","repository_url":"https://github.com/RVC-Boss/GPT-SoVITS","documentation_url":"https://raw.githubusercontent.com/RVC-Boss/GPT-SoVITS/main/README.md","owner_name":"RVC-Boss","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":43,"categories":["audio","video"],"primaryCategory":"audio","selectionReason":"Phù hợp Voice & Âm nhạc: Từ mẫu giọng ngắn đến thử nghiệm TTS và bộ dữ liệu giọng riêng. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Từ mẫu giọng ngắn đến thử nghiệm TTS và bộ dữ liệu giọng riêng.","highlights":["Tổng hợp theo mẫu và tinh chỉnh giọng.","Có tách giọng, chia dữ liệu, ASR và gán văn bản trong WebUI.","README liệt kê Anh, Nhật, Hàn, Quảng Đông và Trung cho suy luận liên ngôn ngữ."],"example":"Chuẩn bị tập đọc của chính bạn để thử quy trình tạo voice ở ngôn ngữ được hỗ trợ.","setup":"Chọn gói Windows hoặc môi trường phù hợp theo hướng dẫn; tải model từ liên kết chính chủ.","limitations":"Không mặc định hỗ trợ tiếng Việt. README cảnh báo huấn luyện GPU Mac có vấn đề chất lượng; kiểm tra quyền của dữ liệu, checkpoint và người có giọng được dùng.","github":{"stars":61502,"forks":6645,"observedAt":"2026-09-03T16:08:41.657Z","url":"https://github.com/RVC-Boss/GPT-SoVITS","pushedAt":"2026-08-18T09:16:25Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/RVC-Boss/GPT-SoVITS/main/README.md","observedAt":"2026-09-03T16:10:16.351Z","sha256":"f90972ccb8733da85e7e2258b262d5ac80a27f3213df5516c9987d808cb2f6c6"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"RVC-Boss/GPT-SoVITS:metadata","source_url":"https://github.com/RVC-Boss/GPT-SoVITS","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Afishaudio%2Ffish-speech%20repo%3ARVC-Project%2FRetrieval-based-Voice-Conversion-WebUI%20repo%3ARVC-Boss%2FGPT-SoVITS%20repo%3Aresemble-ai%2Fchatterbox%20repo%3Amyshell-ai%2FOpenVoice%20repo%3Amyshell-ai%2FMeloTTS%20repo%3Asuno-ai%2Fbark%20repo%3Aace-step%2FACE-Step&per_page=100","stars":61502,"forks":6645,"license":"MIT"},"fetched_at":"2026-09-03T16:08:41.657Z"},{"source_type":"github","source_identifier":"RVC-Boss/GPT-SoVITS:readme:f90972ccb8733da85e7e2258b262d5ac80a27f3213df5516c9987d808cb2f6c6","source_url":"https://raw.githubusercontent.com/RVC-Boss/GPT-SoVITS/main/README.md","raw_metadata":{"sha256":"f90972ccb8733da85e7e2258b262d5ac80a27f3213df5516c9987d808cb2f6c6","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:16.351Z"}],"expected":null},{"identity":"repo:https://github.com/suno-ai/bark","slug":"bark-5d25ba75","name":"Bark","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Không chỉ đọc chữ: thử tiếng cười, tiếng thở và biểu cảm cho một cảnh ngắn.","description":"Bark là mô hình text-to-audio của Suno, có thể tạo lời nói và âm thanh phi ngôn ngữ. Nó khác dịch vụ text-to-music Suno và khác TTS đọc đúng từng chữ: chính chủ cảnh báo kết quả có thể đi chệch prompt.","long_description":"ĐIỂM NỔI BẬT\n• Có các preset người nói và hỗ trợ nhiều ngôn ngữ.\n• Có thể tạo biểu cảm như cười, thở dài hoặc âm thanh đơn giản.\n• Có notebook cho đoạn dài và lựa chọn model nhỏ hơn.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nThử một câu thoại tiếng Anh có tiếng cười cho storyboard, nghe lại trước khi quyết định dùng trong bản dựng.\n\nBẮT ĐẦU\nTheo đúng repo suno-ai/bark; README cảnh báo gói tên bark trên PyPI là dự án khác.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nKhông hỗ trợ custom voice cloning theo README. Mặc định hợp đoạn khoảng 13 giây; có thể tự thêm âm hoặc lời, nên không dùng chưa kiểm tra cho thông tin cần đọc chính xác.","canonical_url":"https://github.com/suno-ai/bark","repository_url":"https://github.com/suno-ai/bark","documentation_url":"https://raw.githubusercontent.com/suno-ai/bark/main/README.md","owner_name":"suno-ai","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":44,"categories":["audio","video"],"primaryCategory":"audio","selectionReason":"Phù hợp Voice & Âm nhạc: Không chỉ đọc chữ: thử tiếng cười, tiếng thở và biểu cảm cho một cảnh ngắn. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Không chỉ đọc chữ: thử tiếng cười, tiếng thở và biểu cảm cho một cảnh ngắn.","highlights":["Có các preset người nói và hỗ trợ nhiều ngôn ngữ.","Có thể tạo biểu cảm như cười, thở dài hoặc âm thanh đơn giản.","Có notebook cho đoạn dài và lựa chọn model nhỏ hơn."],"example":"Thử một câu thoại tiếng Anh có tiếng cười cho storyboard, nghe lại trước khi quyết định dùng trong bản dựng.","setup":"Theo đúng repo suno-ai/bark; README cảnh báo gói tên bark trên PyPI là dự án khác.","limitations":"Không hỗ trợ custom voice cloning theo README. Mặc định hợp đoạn khoảng 13 giây; có thể tự thêm âm hoặc lời, nên không dùng chưa kiểm tra cho thông tin cần đọc chính xác.","github":{"stars":39259,"forks":4665,"observedAt":"2026-09-03T16:08:41.657Z","url":"https://github.com/suno-ai/bark","pushedAt":"2024-08-19T07:45:36Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/suno-ai/bark/main/README.md","observedAt":"2026-09-03T16:10:17.188Z","sha256":"727acc4ec3d37ad8e20a8333fb779edece39271f3be9a813019d01849b256c72"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"suno-ai/bark:metadata","source_url":"https://github.com/suno-ai/bark","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Afishaudio%2Ffish-speech%20repo%3ARVC-Project%2FRetrieval-based-Voice-Conversion-WebUI%20repo%3ARVC-Boss%2FGPT-SoVITS%20repo%3Aresemble-ai%2Fchatterbox%20repo%3Amyshell-ai%2FOpenVoice%20repo%3Amyshell-ai%2FMeloTTS%20repo%3Asuno-ai%2Fbark%20repo%3Aace-step%2FACE-Step&per_page=100","stars":39259,"forks":4665,"license":"MIT"},"fetched_at":"2026-09-03T16:08:41.657Z"},{"source_type":"github","source_identifier":"suno-ai/bark:readme:727acc4ec3d37ad8e20a8333fb779edece39271f3be9a813019d01849b256c72","source_url":"https://raw.githubusercontent.com/suno-ai/bark/main/README.md","raw_metadata":{"sha256":"727acc4ec3d37ad8e20a8333fb779edece39271f3be9a813019d01849b256c72","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:17.188Z"}],"expected":null},{"identity":"repo:https://github.com/rvc-project/retrieval-based-voice-conversion-webui","slug":"rvc-webui-76d8de6a","name":"RVC WebUI","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Giữ phần trình diễn gốc, thử đổi màu giọng bằng một mô hình được cấp quyền.","description":"RVC WebUI tập trung chuyển đổi âm sắc từ audio, khác với TTS tạo giọng trực tiếp từ chữ. Nó có giao diện huấn luyện/suy luận và biến giọng thời gian thực. Hữu ích cho thử nghiệm âm thanh có sự đồng ý, không phải công cụ tạo bản cover của bất kỳ nghệ sĩ nào một cách mặc nhiên hợp pháp.","long_description":"ĐIỂM NỔI BẬT\n• Huấn luyện từ dữ liệu giọng và chuyển đổi bằng cơ chế truy hồi đặc trưng.\n• Có trộn model và lựa chọn tách giọng/nhạc.\n• Có GUI real-time, nhưng độ trễ phụ thuộc driver và phần cứng.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nDùng bản thu và model giọng của chính bạn để tạo hai biến thể nhân vật hư cấu.\n\nBẮT ĐẦU\nTheo nhánh hiện tại dùng Python 3.12, chọn phụ thuộc đúng GPU/CPU và chuẩn bị dữ liệu sạch.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nREADME khuyên ít nhất khoảng 10 phút audio ít nhiễu để huấn luyện. Quyền bài hát, bản thu và giọng là các quyền riêng; không mạo danh hay dùng model không rõ nguồn.","canonical_url":"https://github.com/RVC-Project/Retrieval-based-Voice-Conversion-WebUI","repository_url":"https://github.com/RVC-Project/Retrieval-based-Voice-Conversion-WebUI","documentation_url":"https://raw.githubusercontent.com/RVC-Project/Retrieval-based-Voice-Conversion-WebUI/main/README.md","owner_name":"RVC-Project","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":45,"categories":["audio","video"],"primaryCategory":"audio","selectionReason":"Phù hợp Voice & Âm nhạc: Giữ phần trình diễn gốc, thử đổi màu giọng bằng một mô hình được cấp quyền. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Giữ phần trình diễn gốc, thử đổi màu giọng bằng một mô hình được cấp quyền.","highlights":["Huấn luyện từ dữ liệu giọng và chuyển đổi bằng cơ chế truy hồi đặc trưng.","Có trộn model và lựa chọn tách giọng/nhạc.","Có GUI real-time, nhưng độ trễ phụ thuộc driver và phần cứng."],"example":"Dùng bản thu và model giọng của chính bạn để tạo hai biến thể nhân vật hư cấu.","setup":"Theo nhánh hiện tại dùng Python 3.12, chọn phụ thuộc đúng GPU/CPU và chuẩn bị dữ liệu sạch.","limitations":"README khuyên ít nhất khoảng 10 phút audio ít nhiễu để huấn luyện. Quyền bài hát, bản thu và giọng là các quyền riêng; không mạo danh hay dùng model không rõ nguồn.","github":{"stars":38042,"forks":5257,"observedAt":"2026-09-03T16:08:41.657Z","url":"https://github.com/RVC-Project/Retrieval-based-Voice-Conversion-WebUI","pushedAt":"2026-08-04T07:47:32Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/RVC-Project/Retrieval-based-Voice-Conversion-WebUI/main/README.md","observedAt":"2026-09-03T16:10:17.873Z","sha256":"6ae347c0cc60836f1e7fd2b73ee73327746e66c32a5dd4270d02a096810bca8b"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"RVC-Project/Retrieval-based-Voice-Conversion-WebUI:metadata","source_url":"https://github.com/RVC-Project/Retrieval-based-Voice-Conversion-WebUI","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Afishaudio%2Ffish-speech%20repo%3ARVC-Project%2FRetrieval-based-Voice-Conversion-WebUI%20repo%3ARVC-Boss%2FGPT-SoVITS%20repo%3Aresemble-ai%2Fchatterbox%20repo%3Amyshell-ai%2FOpenVoice%20repo%3Amyshell-ai%2FMeloTTS%20repo%3Asuno-ai%2Fbark%20repo%3Aace-step%2FACE-Step&per_page=100","stars":38042,"forks":5257,"license":"MIT"},"fetched_at":"2026-09-03T16:08:41.657Z"},{"source_type":"github","source_identifier":"RVC-Project/Retrieval-based-Voice-Conversion-WebUI:readme:6ae347c0cc60836f1e7fd2b73ee73327746e66c32a5dd4270d02a096810bca8b","source_url":"https://raw.githubusercontent.com/RVC-Project/Retrieval-based-Voice-Conversion-WebUI/main/README.md","raw_metadata":{"sha256":"6ae347c0cc60836f1e7fd2b73ee73327746e66c32a5dd4270d02a096810bca8b","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:17.873Z"}],"expected":null},{"identity":"repo:https://github.com/myshell-ai/openvoice","slug":"openvoice-f001ee4e","name":"OpenVoice","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Giữ màu giọng khi đổi ngôn ngữ, đồng thời điều chỉnh cách thể hiện.","description":"OpenVoice tách khả năng giữ âm sắc tham chiếu và điều khiển phong cách giọng như nhịp, cảm xúc, ngắt nghỉ. V2 bổ sung chất lượng và các ngôn ngữ hỗ trợ trực tiếp. Đây là ứng viên cho bản địa hóa voice có quyền sử dụng rõ ràng.","long_description":"ĐIỂM NỔI BẬT\n• Clone màu giọng từ tham chiếu và tạo lời nói nhiều ngôn ngữ.\n• Điều khiển nhịp, ngắt nghỉ, ngữ điệu và phong cách.\n• V1/V2 được chính chủ công bố MIT, gồm sử dụng thương mại.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nThử bản tiếng Anh và tiếng Nhật cho nội dung của bạn bằng giọng tham chiếu đã được cho phép.\n\nBẮT ĐẦU\nTheo trang usage được README dẫn, chọn V1/V2 và tải đủ thành phần phụ thuộc.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nNgôn ngữ native của V2 được nêu là Anh, Tây Ban Nha, Pháp, Trung, Nhật, Hàn; không hứa có tiếng Việt sẵn. MIT không thay thế sự đồng ý của chủ giọng.","canonical_url":"https://github.com/myshell-ai/OpenVoice","repository_url":"https://github.com/myshell-ai/OpenVoice","documentation_url":"https://raw.githubusercontent.com/myshell-ai/OpenVoice/main/README.md","owner_name":"myshell-ai","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":46,"categories":["audio","video"],"primaryCategory":"audio","selectionReason":"Phù hợp Voice & Âm nhạc: Giữ màu giọng khi đổi ngôn ngữ, đồng thời điều chỉnh cách thể hiện. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Giữ màu giọng khi đổi ngôn ngữ, đồng thời điều chỉnh cách thể hiện.","highlights":["Clone màu giọng từ tham chiếu và tạo lời nói nhiều ngôn ngữ.","Điều khiển nhịp, ngắt nghỉ, ngữ điệu và phong cách.","V1/V2 được chính chủ công bố MIT, gồm sử dụng thương mại."],"example":"Thử bản tiếng Anh và tiếng Nhật cho nội dung của bạn bằng giọng tham chiếu đã được cho phép.","setup":"Theo trang usage được README dẫn, chọn V1/V2 và tải đủ thành phần phụ thuộc.","limitations":"Ngôn ngữ native của V2 được nêu là Anh, Tây Ban Nha, Pháp, Trung, Nhật, Hàn; không hứa có tiếng Việt sẵn. MIT không thay thế sự đồng ý của chủ giọng.","github":{"stars":37432,"forks":4193,"observedAt":"2026-09-03T16:08:41.657Z","url":"https://github.com/myshell-ai/OpenVoice","pushedAt":"2025-04-19T16:00:00Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/myshell-ai/OpenVoice/main/README.md","observedAt":"2026-09-03T16:10:18.569Z","sha256":"3c6f5d24798763ebb9ca5fea8a1cbd21b935a140300ba531138b5518cd297dfc"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"myshell-ai/OpenVoice:metadata","source_url":"https://github.com/myshell-ai/OpenVoice","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Afishaudio%2Ffish-speech%20repo%3ARVC-Project%2FRetrieval-based-Voice-Conversion-WebUI%20repo%3ARVC-Boss%2FGPT-SoVITS%20repo%3Aresemble-ai%2Fchatterbox%20repo%3Amyshell-ai%2FOpenVoice%20repo%3Amyshell-ai%2FMeloTTS%20repo%3Asuno-ai%2Fbark%20repo%3Aace-step%2FACE-Step&per_page=100","stars":37432,"forks":4193,"license":"MIT"},"fetched_at":"2026-09-03T16:08:41.657Z"},{"source_type":"github","source_identifier":"myshell-ai/OpenVoice:readme:3c6f5d24798763ebb9ca5fea8a1cbd21b935a140300ba531138b5518cd297dfc","source_url":"https://raw.githubusercontent.com/myshell-ai/OpenVoice/main/README.md","raw_metadata":{"sha256":"3c6f5d24798763ebb9ca5fea8a1cbd21b935a140300ba531138b5518cd297dfc","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:18.569Z"}],"expected":null},{"identity":"repo:https://github.com/fishaudio/fish-speech","slug":"fish-speech-ae2c6138","name":"Fish Speech","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Đánh dấu cảm xúc ngay trong câu để thử lời đọc có diễn xuất.","description":"Fish Speech hiện giới thiệu Fish Audio S2 Pro, tập trung TTS đa ngôn ngữ và điều khiển cách đọc bằng thẻ ngôn ngữ tự nhiên. Điểm đáng chú ý cho creator là mô tả thì thầm, nhấn mạnh hoặc phản ứng trong kịch bản. Các tuyên bố dẫn đầu benchmark trong README là kết quả phía tác giả công bố.","long_description":"ĐIỂM NỔI BẬT\n• Chèn hướng dẫn cảm xúc/nhịp điệu ở vị trí cụ thể trong văn bản.\n• Hỗ trợ nhiều người nói và hội thoại nhiều lượt theo chính chủ.\n• Có tài liệu CLI, WebUI, server và Docker.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nThử hai cách diễn đạt cho đoạn mở đầu cùng một script, so độ rõ và tự nhiên trước khi chọn.\n\nBẮT ĐẦU\nTheo tài liệu S2 đúng phiên bản và kiểm tra cấu hình máy cùng điều khoản trước khi tải model.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nCode và trọng số hiện mang FISH AUDIO RESEARCH LICENSE, không phải MIT/Apache thông thường. Kiểm tra quyền thương mại và ngôn ngữ thực tế trước khi đưa vào kit bán.","canonical_url":"https://github.com/fishaudio/fish-speech","repository_url":"https://github.com/fishaudio/fish-speech","documentation_url":"https://raw.githubusercontent.com/fishaudio/fish-speech/main/README.md","owner_name":"fishaudio","license":"FISH AUDIO RESEARCH LICENSE cho code và trọng số theo README hiện tại.","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":47,"categories":["audio","video"],"primaryCategory":"audio","selectionReason":"Phù hợp Voice & Âm nhạc: Đánh dấu cảm xúc ngay trong câu để thử lời đọc có diễn xuất. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Đánh dấu cảm xúc ngay trong câu để thử lời đọc có diễn xuất.","highlights":["Chèn hướng dẫn cảm xúc/nhịp điệu ở vị trí cụ thể trong văn bản.","Hỗ trợ nhiều người nói và hội thoại nhiều lượt theo chính chủ.","Có tài liệu CLI, WebUI, server và Docker."],"example":"Thử hai cách diễn đạt cho đoạn mở đầu cùng một script, so độ rõ và tự nhiên trước khi chọn.","setup":"Theo tài liệu S2 đúng phiên bản và kiểm tra cấu hình máy cùng điều khoản trước khi tải model.","limitations":"Code và trọng số hiện mang FISH AUDIO RESEARCH LICENSE, không phải MIT/Apache thông thường. Kiểm tra quyền thương mại và ngôn ngữ thực tế trước khi đưa vào kit bán.","github":{"stars":32524,"forks":2802,"observedAt":"2026-09-03T16:08:41.657Z","url":"https://github.com/fishaudio/fish-speech","pushedAt":"2026-08-22T08:55:50Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/fishaudio/fish-speech/main/README.md","observedAt":"2026-09-03T16:10:19.450Z","sha256":"23193581f6c9a0dd174cd1427e670d64a0aeda11394f627a124b78876a23d544"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"fishaudio/fish-speech:metadata","source_url":"https://github.com/fishaudio/fish-speech","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Afishaudio%2Ffish-speech%20repo%3ARVC-Project%2FRetrieval-based-Voice-Conversion-WebUI%20repo%3ARVC-Boss%2FGPT-SoVITS%20repo%3Aresemble-ai%2Fchatterbox%20repo%3Amyshell-ai%2FOpenVoice%20repo%3Amyshell-ai%2FMeloTTS%20repo%3Asuno-ai%2Fbark%20repo%3Aace-step%2FACE-Step&per_page=100","stars":32524,"forks":2802,"license":"NOASSERTION"},"fetched_at":"2026-09-03T16:08:41.657Z"},{"source_type":"github","source_identifier":"fishaudio/fish-speech:readme:23193581f6c9a0dd174cd1427e670d64a0aeda11394f627a124b78876a23d544","source_url":"https://raw.githubusercontent.com/fishaudio/fish-speech/main/README.md","raw_metadata":{"sha256":"23193581f6c9a0dd174cd1427e670d64a0aeda11394f627a124b78876a23d544","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:19.450Z"}],"expected":null},{"identity":"repo:https://github.com/resemble-ai/chatterbox","slug":"chatterbox-371967c1","name":"Chatterbox","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Một họ TTS với lựa chọn riêng cho đa ngôn ngữ, tiếng Anh nhanh và máy hạn chế bộ nhớ.","description":"Chatterbox của Resemble AI có nhiều biến thể thay vì một model dùng cho mọi mục đích. README hiện giới thiệu Multilingual V3, Turbo và Nano, cùng các gói ngôn ngữ chuyên biệt. Điều này giúp chọn voice theo nhu cầu thực tế của kênh.","long_description":"ĐIỂM NỔI BẬT\n• Multilingual V3 hướng tới nhiều ngôn ngữ và giữ đặc trưng người nói.\n• Turbo tiếng Anh hỗ trợ các thẻ như cười hoặc ho.\n• Nano nhắm tới thiết bị/CPU có giới hạn tài nguyên.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nSo bản voice tiếng Anh từ Turbo và Nano trên cùng đoạn script trước khi chọn tốc độ/chất lượng phù hợp.\n\nBẮT ĐẦU\nChọn đúng model trong bảng Model Zoo và làm theo ví dụ chính chủ.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nTurbo/Nano được liệt kê tiếng Anh, không đánh đồng với bản multilingual. Cần đối chiếu danh sách tiếng Việt, quyền mẫu giọng và nghe soát nội dung sinh thêm/lặp.","canonical_url":"https://github.com/resemble-ai/chatterbox","repository_url":"https://github.com/resemble-ai/chatterbox","documentation_url":"https://raw.githubusercontent.com/resemble-ai/chatterbox/master/README.md","owner_name":"resemble-ai","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":48,"categories":["audio","video"],"primaryCategory":"audio","selectionReason":"Phù hợp Voice & Âm nhạc: Một họ TTS với lựa chọn riêng cho đa ngôn ngữ, tiếng Anh nhanh và máy hạn chế bộ nhớ. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Một họ TTS với lựa chọn riêng cho đa ngôn ngữ, tiếng Anh nhanh và máy hạn chế bộ nhớ.","highlights":["Multilingual V3 hướng tới nhiều ngôn ngữ và giữ đặc trưng người nói.","Turbo tiếng Anh hỗ trợ các thẻ như cười hoặc ho.","Nano nhắm tới thiết bị/CPU có giới hạn tài nguyên."],"example":"So bản voice tiếng Anh từ Turbo và Nano trên cùng đoạn script trước khi chọn tốc độ/chất lượng phù hợp.","setup":"Chọn đúng model trong bảng Model Zoo và làm theo ví dụ chính chủ.","limitations":"Turbo/Nano được liệt kê tiếng Anh, không đánh đồng với bản multilingual. Cần đối chiếu danh sách tiếng Việt, quyền mẫu giọng và nghe soát nội dung sinh thêm/lặp.","github":{"stars":26246,"forks":3538,"observedAt":"2026-09-03T16:08:41.657Z","url":"https://github.com/resemble-ai/chatterbox","pushedAt":"2026-07-21T12:27:05Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/resemble-ai/chatterbox/master/README.md","observedAt":"2026-09-03T16:10:20.066Z","sha256":"fd9315cc529c65d46ddd21ded05ba3372b6f6f39242bd015f770145bf5e0448f"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"resemble-ai/chatterbox:metadata","source_url":"https://github.com/resemble-ai/chatterbox","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Afishaudio%2Ffish-speech%20repo%3ARVC-Project%2FRetrieval-based-Voice-Conversion-WebUI%20repo%3ARVC-Boss%2FGPT-SoVITS%20repo%3Aresemble-ai%2Fchatterbox%20repo%3Amyshell-ai%2FOpenVoice%20repo%3Amyshell-ai%2FMeloTTS%20repo%3Asuno-ai%2Fbark%20repo%3Aace-step%2FACE-Step&per_page=100","stars":26246,"forks":3538,"license":"MIT"},"fetched_at":"2026-09-03T16:08:41.657Z"},{"source_type":"github","source_identifier":"resemble-ai/chatterbox:readme:fd9315cc529c65d46ddd21ded05ba3372b6f6f39242bd015f770145bf5e0448f","source_url":"https://raw.githubusercontent.com/resemble-ai/chatterbox/master/README.md","raw_metadata":{"sha256":"fd9315cc529c65d46ddd21ded05ba3372b6f6f39242bd015f770145bf5e0448f","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:20.066Z"}],"expected":null},{"identity":"repo:https://github.com/anjok07/ultimatevocalremovergui","slug":"ultimate-vocal-remover-e15c0b2c","name":"Ultimate Vocal Remover","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Tách phần giọng và phần nhạc để có thêm quyền kiểm soát khi hậu kỳ.","description":"Ultimate Vocal Remover là ứng dụng có giao diện cho các mô hình tách nguồn âm thanh. Nó hữu ích khi xử lý bản thu được phép, chuẩn bị voice hoặc giảm ảnh hưởng nhạc nền trước khâu nhận dạng. Tách được âm không có nghĩa được quyền sử dụng lại bản nhạc.","long_description":"ĐIỂM NỔI BẬT\n• Nhiều mô hình tách vocal và phần nhạc.\n• Có gói Windows/macOS kèm phần lớn môi trường cần thiết.\n• Có lựa chọn tăng tốc phù hợp một số GPU và Apple Silicon.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nTách lời của buổi quay do bạn sở hữu để kiểm tra xem ASR nhận tốt hơn hay không.\n\nBẮT ĐẦU\nTải gói chính chủ đúng kiến trúc; kiểm tra bản phát hành và cảnh báo bảo mật của hệ điều hành.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nCó thể còn tiếng nhạc hoặc tạo méo âm. Không làm theo bước tắt bảo mật toàn hệ thống chỉ để mở app; ưu tiên bản đã xác minh và giữ file gốc.","canonical_url":"https://github.com/Anjok07/ultimatevocalremovergui","repository_url":"https://github.com/Anjok07/ultimatevocalremovergui","documentation_url":"https://raw.githubusercontent.com/Anjok07/ultimatevocalremovergui/master/README.md","owner_name":"Anjok07","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":49,"categories":["audio","video"],"primaryCategory":"audio","selectionReason":"Phù hợp Voice & Âm nhạc: Tách phần giọng và phần nhạc để có thêm quyền kiểm soát khi hậu kỳ. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Tách phần giọng và phần nhạc để có thêm quyền kiểm soát khi hậu kỳ.","highlights":["Nhiều mô hình tách vocal và phần nhạc.","Có gói Windows/macOS kèm phần lớn môi trường cần thiết.","Có lựa chọn tăng tốc phù hợp một số GPU và Apple Silicon."],"example":"Tách lời của buổi quay do bạn sở hữu để kiểm tra xem ASR nhận tốt hơn hay không.","setup":"Tải gói chính chủ đúng kiến trúc; kiểm tra bản phát hành và cảnh báo bảo mật của hệ điều hành.","limitations":"Có thể còn tiếng nhạc hoặc tạo méo âm. Không làm theo bước tắt bảo mật toàn hệ thống chỉ để mở app; ưu tiên bản đã xác minh và giữ file gốc.","github":{"stars":26099,"forks":1987,"observedAt":"2026-09-03T16:08:48.098Z","url":"https://github.com/Anjok07/ultimatevocalremovergui","pushedAt":"2025-03-13T21:44:03Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/Anjok07/ultimatevocalremovergui/master/README.md","observedAt":"2026-09-03T16:10:26.071Z","sha256":"07c50db9c654342b1d1cc57448cf52ec1a6d73e45216d1cb0bb815c332042dbd"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"Anjok07/ultimatevocalremovergui:metadata","source_url":"https://github.com/Anjok07/ultimatevocalremovergui","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Aace-step%2FACE-Step-1.5%20repo%3Afacebookresearch%2Faudiocraft%20repo%3AAnjok07%2Fultimatevocalremovergui%20repo%3Aaudacity%2Faudacity%20repo%3AComfy-Org%2FComfyUI%20repo%3AAUTOMATIC1111%2Fstable-diffusion-webui%20repo%3Alllyasviel%2FFooocus%20repo%3Ainvoke-ai%2FInvokeAI&per_page=100","stars":26099,"forks":1987,"license":"MIT"},"fetched_at":"2026-09-03T16:08:48.098Z"},{"source_type":"github","source_identifier":"Anjok07/ultimatevocalremovergui:readme:07c50db9c654342b1d1cc57448cf52ec1a6d73e45216d1cb0bb815c332042dbd","source_url":"https://raw.githubusercontent.com/Anjok07/ultimatevocalremovergui/master/README.md","raw_metadata":{"sha256":"07c50db9c654342b1d1cc57448cf52ec1a6d73e45216d1cb0bb815c332042dbd","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:26.071Z"}],"expected":null},{"identity":"repo:https://github.com/facebookresearch/audiocraft","slug":"audiocraft-0188a327","name":"AudioCraft","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Khám phá cách AI tạo nhạc và âm thanh — với ranh giới nghiên cứu/thương mại rõ ràng.","description":"AudioCraft là thư viện nghiên cứu audio của Meta, chứa các mô hình như MusicGen, AudioGen và các biến thể điều khiển nhạc. Nó phù hợp tìm hiểu, thử nghiệm ý tưởng âm thanh và pipeline nghiên cứu; không nên mặc định đưa trọng số vào sản phẩm thương mại.","long_description":"ĐIỂM NỔI BẬT\n• MusicGen cho nhạc từ mô tả; AudioGen cho âm thanh.\n• Có các hướng điều khiển theo style, giai điệu/hợp âm ở model tương ứng.\n• Công khai mã huấn luyện, suy luận và tài liệu theo từng model.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nThử mô tả âm thanh cho storyboard nghiên cứu rồi tìm hoặc tạo bản thay thế có quyền thương mại nếu cần đăng kiếm tiền.\n\nBẮT ĐẦU\nĐọc yêu cầu Python/PyTorch và tài liệu riêng của model được chọn; chuẩn bị FFmpeg.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nMã MIT nhưng trọng số CC-BY-NC 4.0. Không coi mã nguồn mở là đã có quyền dùng mọi đầu ra trong quảng cáo hay kênh thương mại.","canonical_url":"https://github.com/facebookresearch/audiocraft","repository_url":"https://github.com/facebookresearch/audiocraft","documentation_url":"https://raw.githubusercontent.com/facebookresearch/audiocraft/main/README.md","owner_name":"facebookresearch","license":"Code MIT; trọng số CC-BY-NC-4.0 theo LICENSE_weights.","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":50,"categories":["audio","video"],"primaryCategory":"audio","selectionReason":"Phù hợp Voice & Âm nhạc: Khám phá cách AI tạo nhạc và âm thanh — với ranh giới nghiên cứu/thương mại rõ ràng. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Khám phá cách AI tạo nhạc và âm thanh — với ranh giới nghiên cứu/thương mại rõ ràng.","highlights":["MusicGen cho nhạc từ mô tả; AudioGen cho âm thanh.","Có các hướng điều khiển theo style, giai điệu/hợp âm ở model tương ứng.","Công khai mã huấn luyện, suy luận và tài liệu theo từng model."],"example":"Thử mô tả âm thanh cho storyboard nghiên cứu rồi tìm hoặc tạo bản thay thế có quyền thương mại nếu cần đăng kiếm tiền.","setup":"Đọc yêu cầu Python/PyTorch và tài liệu riêng của model được chọn; chuẩn bị FFmpeg.","limitations":"Mã MIT nhưng trọng số CC-BY-NC 4.0. Không coi mã nguồn mở là đã có quyền dùng mọi đầu ra trong quảng cáo hay kênh thương mại.","github":{"stars":23603,"forks":2696,"observedAt":"2026-09-03T16:08:48.098Z","url":"https://github.com/facebookresearch/audiocraft","pushedAt":"2026-03-03T21:50:32Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/facebookresearch/audiocraft/main/README.md","observedAt":"2026-09-03T16:10:26.997Z","sha256":"0240bd901c60c42508680e6beb580574836fd44b8476e721f811831fd2780638"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"facebookresearch/audiocraft:metadata","source_url":"https://github.com/facebookresearch/audiocraft","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Aace-step%2FACE-Step-1.5%20repo%3Afacebookresearch%2Faudiocraft%20repo%3AAnjok07%2Fultimatevocalremovergui%20repo%3Aaudacity%2Faudacity%20repo%3AComfy-Org%2FComfyUI%20repo%3AAUTOMATIC1111%2Fstable-diffusion-webui%20repo%3Alllyasviel%2FFooocus%20repo%3Ainvoke-ai%2FInvokeAI&per_page=100","stars":23603,"forks":2696,"license":"MIT"},"fetched_at":"2026-09-03T16:08:48.098Z"},{"source_type":"github","source_identifier":"facebookresearch/audiocraft:readme:0240bd901c60c42508680e6beb580574836fd44b8476e721f811831fd2780638","source_url":"https://raw.githubusercontent.com/facebookresearch/audiocraft/main/README.md","raw_metadata":{"sha256":"0240bd901c60c42508680e6beb580574836fd44b8476e721f811831fd2780638","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:26.997Z"}],"expected":null}]'::jsonb) loop
